     "background": "Byron Donalds is a Republican U.S. Representative for Florida's 19th Congressional District (Southwest Florida), first elected in 2020 after serving in the Florida House. He announced his campaign for governor in February 2025 with President Trump's endorsement. He won the Aug. 18, 2026 Republican primary with about 47.8% of the vote over Lt. Gov. Jay Collins, former House Speaker Paul Renner and businessman James Fishback. On Aug. 26, 2026, at Miami's Freedom Tower, he named state Sen. Bryan Avila, a Florida National Guard captain first elected to the Florida House in 2014 and to the Senate in 2022, as his running mate. Avila (born 1984 in Hialeah to Cuban exile parents) holds degrees from Miami Dade College, the University of Miami and Florida International University (M.S. criminal justice and M.P.A.), served eight years in the Florida House (2014-2022) where he sponsored the 'Stop WOKE Act,' and has represented part of Miami-Dade in the Florida Senate since 2022 while serving as a captain in the Florida Army National Guard.",
