     "background": "David Jolly is a former U.S. Representative for Florida's 13th District (Pinellas County), serving 2014-2017 as a Republican. He later left the Republican Party, became an independent and then registered as a Democrat before running for governor. He won the Aug. 18, 2026 Democratic primary with about 61% of the vote. On June 10, 2026 he named Gwen Graham, a former Democratic congresswoman (2015-2017), 2018 gubernatorial candidate and daughter of the late Gov. and Sen. Bob Graham, as his running mate; their House service overlapped in 2015-2017. Gwen Graham (born 1963, Miami Lakes) is an attorney and daughter of former Gov. and U.S. Sen. Bob Graham; she represented Florida's 2nd District (2015-2017), finished second in the 2018 Democratic primary for governor with 31.3%, and served as U.S. Assistant Secretary of Education for legislation and congressional affairs in the Biden administration from 2021 to 2025.",
